import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
const ANALYSIS_TYPES = ['통계', '통상급여', '급여변동', '증감', '인건비손익'];
// 가정: 열람 로그의 고정값과 접속 정보 (BEHAVIOR.md 값의 출처가 미정이라 개발 중 정함)
const LOG_EVENT_TYPE = '개인정보열람';
const LOG_TARGET_INFO_TYPE = '급여정보';
const LOG_LOGIN_TYPE = '웹';
const LOG_DEFAULT_IP = '0.0.0.0';
// 가정: 증감액은 직전 동일 길이 기간의 지급 합계 대비 증감액으로 계산한다
const DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;

function textOf(value: unknown): string {
  return typeof value === 'string' ? value.trim() : '';
}

function idOf(value: unknown, label: string): string {
  const text = textOf(value);
  if (text !== '' && !/^\d+$/.test(text)) {
    throw new ApiError(400, 'VALIDATION_FAILED', label + ' 형식이 올바르지 않습니다.');
  }
  return text;
}

function countOf(value: unknown, label: string, fallback: number): number {
  const text = textOf(value);
  if (text === '') {
    return fallback;
  }
  if (!/^\d+$/.test(text)) {
    throw new ApiError(400, 'VALIDATION_FAILED', label + ' 형식이 올바르지 않습니다.');
  }
  return Number(text);
}

@Controller('api/v1')
export class FnSfr02113Controller {
  @Get('/payroll-analyses')
  async listPayrollAnalyses(@Req() req: Request) {
    const user = currentUser(req);
    user.require('급여 담당자');
    const query = checks.queryOf(req.query);
    const analysisType = textOf(query['analysisType']);
    const startDate = textOf(query['startDate']);
    const endDate = textOf(query['endDate']);
    if (!ANALYSIS_TYPES.includes(analysisType)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '분석 유형을 올바르게 선택해 주세요.');
    }
    if (!DATE_PATTERN.test(startDate) || !DATE_PATTERN.test(endDate)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '조회 시작일과 종료일을 YYYY-MM-DD 형식으로 입력해 주세요.');
    }
    if (startDate > endDate) {
      throw new ApiError(422, 'INVALID_PERIOD', '조회 기간이 올바르지 않습니다.');
    }
    const departmentId = idOf(query['departmentId'], '주부서');
    const employeeId = idOf(query['employeeId'], '임직원 ID');
    const page = countOf(query['page'], '쪽 번호', 0);
    const size = Math.min(countOf(query['size'], '쪽 크기', DEFAULT_SIZE), MAX_SIZE);
    if (size < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 크기는 1 이상이어야 합니다.');
    }
    const params: Record<string, unknown> = {
      startDate: startDate,
      endDate: endDate,
    };
    let filter = ' ';
    if (departmentId !== '') {
      filter += 'AND e.department_id = CAST(:departmentId AS bigint) ';
      params['departmentId'] = departmentId;
    }
    if (employeeId !== '') {
      filter += 'AND e.employee_id = CAST(:employeeId AS bigint) ';
      params['employeeId'] = employeeId;
    }
    const periodCurrent = 'd.pay_date BETWEEN CAST(:startDate AS date) AND CAST(:endDate AS date)';
    const periodPrevious = 'd.pay_date BETWEEN CAST(:startDate AS date) - (CAST(:endDate AS date) - CAST(:startDate AS date) + 1) AND CAST(:startDate AS date) - 1';
    const base = ' FROM employee e WHERE EXISTS (SELECT 1 FROM payroll p JOIN payday d ON d.payday_id = p.payday_id WHERE p.employee_id = e.employee_id AND ' + periodCurrent + ')' + filter;
    return transaction(async (db) => {
      await db.execute(
        'INSERT INTO access_log (employee_id, event_type, accessed_at, login_ip, login_type, target_info_type, created_at, updated_at) ' +
          'VALUES (CAST(:userId AS bigint), :eventType, now(), :loginIp, :loginType, :targetInfoType, now(), now())',
        {
          userId: user.id,
          eventType: LOG_EVENT_TYPE,
          loginIp: (req.ip || LOG_DEFAULT_IP).slice(0, 45),
          loginType: LOG_LOGIN_TYPE,
          targetInfoType: LOG_TARGET_INFO_TYPE,
        },
      );
      const totals = await db.query('SELECT COUNT(*) AS "total"' + base, params);
      const total = Number(totals[0]['total']);
      const selectSql =
        'SELECT e.employee_id AS "employeeId", e.name AS "employeeName", ' +
        '(SELECT s.assigned_salary FROM employee_salary s WHERE s.employee_id = e.employee_id AND s.applied_from <= CAST(:endDate AS date) ORDER BY s.applied_from DESC LIMIT 1) AS "assignedSalary", ' +
        '(SELECT COALESCE(SUM(p.total_payment_amount), 0) FROM payroll p JOIN payday d ON d.payday_id = p.payday_id WHERE p.employee_id = e.employee_id AND ' + periodCurrent + ') AS "totalPaymentAmount", ' +
        '(SELECT COALESCE(SUM(i.amount), 0) FROM payroll_item_amount i JOIN payroll p ON p.payroll_id = i.payroll_id JOIN payday d ON d.payday_id = p.payday_id WHERE p.employee_id = e.employee_id AND ' + periodCurrent + ') AS "amount", ' +
        '(SELECT COALESCE(SUM(p.total_payment_amount), 0) FROM payroll p JOIN payday d ON d.payday_id = p.payday_id WHERE p.employee_id = e.employee_id AND ' + periodCurrent + ') - ' +
        '(SELECT COALESCE(SUM(p.total_payment_amount), 0) FROM payroll p JOIN payday d ON d.payday_id = p.payday_id WHERE p.employee_id = e.employee_id AND ' + periodPrevious + ') AS "changeAmount"';
      const rows = await db.query(
        selectSql + base + ' ORDER BY e.employee_id LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)',
        { ...params, size: size, offset: page * size },
      );
      return { items: rows, page: page, size: size, total: total };
    });
  }
}

