import { useState } from 'react';
import { call, useData, Num, Filters, Field, Select, DateInput, LookupSelect, Band, DataTable, Pager, Drawer, Pairs, Tiles, ErrorText, RefName } from '../kit';
import type { PageProps, Row, Page, Column } from '../kit';

const TYPES: [string, string][] = [
  ['통계', '급여통계'],
  ['통상급여', '통상급여'],
  ['급여변동', '급여변동'],
  ['증감', '급여 증감'],
  ['인건비손익', '인건비 손익'],
];

const SIZE = 20;

export default function FnSfr02113Page({ role, notify }: PageProps) {
  const [analysisType, setAnalysisType] = useState('통계');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [departmentId, setDepartmentId] = useState<number | string>('');
  const [employeeId, setEmployeeId] = useState<number | string>('');
  const [applied, setApplied] = useState<Row | null>(null);
  const [pageNo, setPageNo] = useState(0);
  const [detail, setDetail] = useState<Row | null>(null);
  const [formError, setFormError] = useState('');

  const { data, error, loading } = useData<Page>(async () => {
    if (!applied) {
      return { items: [], page: 0, size: SIZE, total: 0 };
    }
    return call<Page>('GET', '/payroll-analyses', role, undefined, { ...applied, page: pageNo, size: SIZE });
  }, [applied, pageNo, role]);

  const search = () => {
    if (!startDate || !endDate) {
      setFormError('조회 시작일과 종료일을 입력해 주세요.');
      return;
    }
    if (startDate > endDate) {
      setFormError('조회 기간이 올바르지 않습니다.');
      return;
    }
    setFormError('');
    setPageNo(0);
    setApplied({ analysisType, startDate, endDate, departmentId, employeeId });
    notify('급여 분석 현황을 조회했습니다.');
  };

  const reset = () => {
    setAnalysisType('통계');
    setStartDate('');
    setEndDate('');
    setDepartmentId('');
    setEmployeeId('');
    setFormError('');
    setPageNo(0);
    setApplied(null);
  };

  const rows = data ? data.items : [];
  const total = data ? data.total : 0;
  const pageSum = rows.reduce((sum, r) => sum + Number(r['totalPaymentAmount'] ?? 0), 0);
  const pageChange = rows.reduce((sum, r) => sum + Number(r['changeAmount'] ?? 0), 0);

  const columns: Column[] = [
    { key: 'employeeName', label: '성명' },
    { key: 'assignedSalary', label: '책정임금', render: (r) => <Num value={r['assignedSalary']} /> },
    { key: 'totalPaymentAmount', label: '지급 합계', render: (r) => <Num value={r['totalPaymentAmount']} /> },
    { key: 'amount', label: '금액', render: (r) => <Num value={r['amount']} /> },
    { key: 'changeAmount', label: '기간 대비 증감액', render: (r) => <Num value={r['changeAmount']} /> },
  ];

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>분석 요약</h2>
        <Tiles
          items={[
            ['조회 인원', <Num value={total} />],
            ['쪽 지급 합계', <Num value={pageSum} />],
            ['쪽 증감액', <Num value={pageChange} />],
          ]}
        />
      </section>
      <section className="box span-12">
        <h2>급여 분석 현황</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="분석 유형" required>
            <Select value={analysisType} onChange={setAnalysisType} options={TYPES} />
          </Field>
          <Field label="조회 시작일" required>
            <DateInput value={startDate} onChange={setStartDate} />
          </Field>
          <Field label="조회 종료일" required>
            <DateInput value={endDate} onChange={setEndDate} />
          </Field>
          <Field label="주부서">
            <LookupSelect table="department" role={role} value={departmentId} onChange={setDepartmentId} placeholder="전체" />
          </Field>
          <Field label="임직원">
            <LookupSelect table="employee" role={role} value={employeeId} onChange={setEmployeeId} placeholder="전체" />
          </Field>
        </Filters>
        {formError ? <ErrorText text={formError} /> : null}
        {error ? <ErrorText text={error} /> : null}
        <Band total={total} />
        <DataTable
          columns={columns}
          rows={rows}
          onRowClick={(r) => setDetail(r)}
          empty={loading ? '불러오는 중입니다.' : '분석 유형과 기간을 선택해 조회해 주세요.'}
        />
        <Pager page={pageNo} size={SIZE} total={total} onPage={setPageNo} />
      </section>
      {detail ? (
        <Drawer title="급여 분석 상세" onClose={() => setDetail(null)}>
          <Pairs
            items={[
              ['임직원 ID', <RefName table="employee" role={role} value={detail['employeeId']} />],
              ['성명', String(detail['employeeName'] ?? '')],
              ['책정임금', <Num value={detail['assignedSalary']} />],
              ['지급 합계', <Num value={detail['totalPaymentAmount']} />],
              ['금액', <Num value={detail['amount']} />],
              ['기간 대비 증감액', <Num value={detail['changeAmount']} />],
            ]}
          />
        </Drawer>
      ) : null}
    </div>
  );
}
